CREATE INDEX IX_ews_code ON dbo.ews_cleaned(code);
CREATE INDEX IX_ews_semester ON dbo.ews_cleaned(semester);
CREATE INDEX IX_ews_source_file ON dbo.ews_cleaned(source_file);
CREATE INDEX IX_ews_target ON dbo.ews_cleaned(target);
CREATE INDEX IX_ews_modeling_ready ON dbo.ews_cleaned(has_prefinal, target);
GO

/* ============================================================
   MODELING-READY VIEW
   - Uses only rows for which at least one pre-final assessment exists.
   - FINAL EXAM and TOTAL are deliberately retained in the raw table,
     but excluded from this modeling view to prevent leakage.
   ============================================================ */
CREATE VIEW dbo.v_ml_prefinal_dataset
AS
SELECT
    record_id,
    semester,
    class_id,
    code,
    source_file,
    row_idx_orig,

    [LABS-10],
    [ASSIGNMENTS-10],
    [PROGRESS TESTS-30],
    [ASSIGNMENTS-30],
    [EXERCISES-30],
    [QUIZ-20],
    [ASSIGNMENTS-20],
    [PRACTICAL EXAM-30],
    [PROGRESS TESTS-20],
    [PROGRESS TESTS-10],
    [QUIZ-10],
    [LABS-15],
    [PRACTICAL EXAM-25],
    [PRESENTATION-20],
    [ACTIVE LEARNING-10],
    [PROJECT-30],
    [EXERCISES-10],
    [LABS-20],
    [PRACTICAL EXAM-40],
    [WORKSHOP-10],
    [PRACTICAL EXAM-20],

    target
FROM dbo.ews_cleaned
WHERE has_prefinal = 1;
GO

/* Optional sensitivity dataset:
   excludes the pipeline's suspicious-total flag.
   Use this only as a robustness check, not as a silent replacement
   for the pipeline-defined modeling-ready dataset. */
CREATE VIEW dbo.v_ml_prefinal_dataset_strict
AS
SELECT *
FROM dbo.v_ml_prefinal_dataset
WHERE record_id IN (
    SELECT record_id
    FROM dbo.ews_cleaned
    WHERE has_prefinal = 1
      AND flag_suspicious_total = 0
);
GO

/* ============================================================
   RQ1 LONG VIEW
   One row per record x pre-final component.
   This preserves the component weight in the component name.
   ============================================================ */
CREATE VIEW dbo.v_rq1_prefinal_long
AS
SELECT
    e.record_id,
    e.semester,
    e.code,
    e.source_file,
    e.target,
    v.assessment_component,
    v.score
FROM dbo.ews_cleaned AS e
CROSS APPLY (VALUES
    (N'LABS-10', e.[LABS-10]),
    (N'ASSIGNMENTS-10', e.[ASSIGNMENTS-10]),
    (N'PROGRESS TESTS-30', e.[PROGRESS TESTS-30]),
    (N'ASSIGNMENTS-30', e.[ASSIGNMENTS-30]),
    (N'EXERCISES-30', e.[EXERCISES-30]),
    (N'QUIZ-20', e.[QUIZ-20]),
    (N'ASSIGNMENTS-20', e.[ASSIGNMENTS-20]),
    (N'PRACTICAL EXAM-30', e.[PRACTICAL EXAM-30]),
    (N'PROGRESS TESTS-20', e.[PROGRESS TESTS-20]),
    (N'PROGRESS TESTS-10', e.[PROGRESS TESTS-10]),
    (N'QUIZ-10', e.[QUIZ-10]),
    (N'LABS-15', e.[LABS-15]),
    (N'PRACTICAL EXAM-25', e.[PRACTICAL EXAM-25]),
    (N'PRESENTATION-20', e.[PRESENTATION-20]),
    (N'ACTIVE LEARNING-10', e.[ACTIVE LEARNING-10]),
    (N'PROJECT-30', e.[PROJECT-30]),
    (N'EXERCISES-10', e.[EXERCISES-10]),
    (N'LABS-20', e.[LABS-20]),
    (N'PRACTICAL EXAM-40', e.[PRACTICAL EXAM-40]),
    (N'WORKSHOP-10', e.[WORKSHOP-10]),
    (N'PRACTICAL EXAM-20', e.[PRACTICAL EXAM-20])
) AS v(assessment_component, score)
WHERE e.has_prefinal = 1
  AND v.score IS NOT NULL;
GO

/* ============================================================
   VERIFICATION - MUST MATCH cleaned pipeline metadata
   Expected:
     all_rows            = 124791
     target_0            = 92179
     target_1            = 32612
     modeling_ready_rows = 110704
     distinct_codes      = 15201
     source_files        = 18
   ============================================================ */
SELECT COUNT_BIG(*) AS all_rows FROM dbo.ews_cleaned;
SELECT target, COUNT_BIG(*) AS n FROM dbo.ews_cleaned GROUP BY target ORDER BY target;
SELECT COUNT_BIG(*) AS modeling_ready_rows FROM dbo.v_ml_prefinal_dataset;
SELECT COUNT(DISTINCT code) AS distinct_codes FROM dbo.ews_cleaned;
SELECT COUNT(DISTINCT source_file) AS source_files FROM dbo.ews_cleaned;
GO

/* ============================================================
   RQ1
   Which pre-final-exam assessment components are most strongly
   associated with an unsuccessful course outcome?
   Point-biserial correlation = Pearson(score, binary target).
   target=1 means unsuccessful.
   ============================================================ */
WITH s AS
(
    SELECT
        assessment_component,
        COUNT_BIG(*) AS n,
        SUM(CAST(score AS FLOAT)) AS sx,
        SUM(CAST(target AS FLOAT)) AS sy,
        SUM(CAST(score AS FLOAT) * CAST(target AS FLOAT)) AS sxy,
        SUM(CAST(score AS FLOAT) * CAST(score AS FLOAT)) AS sx2,
        SUM(CAST(target AS FLOAT) * CAST(target AS FLOAT)) AS sy2,
        AVG(CASE WHEN target = 0 THEN CAST(score AS FLOAT) END) AS avg_success,
        AVG(CASE WHEN target = 1 THEN CAST(score AS FLOAT) END) AS avg_unsuccessful
    FROM dbo.v_rq1_prefinal_long
    GROUP BY assessment_component
    HAVING COUNT_BIG(*) >= 30
)
SELECT
    assessment_component,
    n,
    CAST(avg_success AS DECIMAL(10,3)) AS avg_score_successful,
    CAST(avg_unsuccessful AS DECIMAL(10,3)) AS avg_score_unsuccessful,
    CAST(avg_success - avg_unsuccessful AS DECIMAL(10,3)) AS mean_score_gap,
    CAST(
        (n * sxy - sx * sy) /
        NULLIF(SQRT((n * sx2 - sx * sx) * (n * sy2 - sy * sy)), 0)
        AS DECIMAL(12,6)
    ) AS correlation_with_unsuccessful,
    CAST(ABS(
        (n * sxy - sx * sy) /
        NULLIF(SQRT((n * sx2 - sx * sx) * (n * sy2 - sy * sy)), 0)
    ) AS DECIMAL(12,6)) AS absolute_correlation
FROM s
ORDER BY absolute_correlation DESC;
GO

/* RQ1 supporting table: unsuccessful rate by score band */
SELECT
    assessment_component,
    CASE
        WHEN score < 5.0 THEN N'<5.0'
        WHEN score < 6.5 THEN N'5.0-6.4'
        WHEN score < 8.0 THEN N'6.5-7.9'
        ELSE N'8.0-10.0'
    END AS score_band,
    COUNT_BIG(*) AS n,
    CAST(100.0 * AVG(CAST(target AS FLOAT)) AS DECIMAL(10,2)) AS unsuccessful_pct
FROM dbo.v_rq1_prefinal_long
GROUP BY
    assessment_component,
    CASE
        WHEN score < 5.0 THEN N'<5.0'
        WHEN score < 6.5 THEN N'5.0-6.4'
        WHEN score < 8.0 THEN N'6.5-7.9'
        ELSE N'8.0-10.0'
    END
HAVING COUNT_BIG(*) >= 20
ORDER BY assessment_component, score_band;
GO

/* ============================================================
   RQ2
   SQL prepares the exact modeling dataset.
   The 5 algorithms must be trained/evaluated in Python.
   ============================================================ */
SELECT target, COUNT_BIG(*) AS n,
       CAST(100.0 * COUNT_BIG(*) / SUM(COUNT_BIG(*)) OVER() AS DECIMAL(10,2)) AS pct
FROM dbo.v_ml_prefinal_dataset
GROUP BY target
ORDER BY target;
GO

-- Export this result to CSV for Python:
SELECT *
FROM dbo.v_ml_prefinal_dataset
ORDER BY record_id;
GO

/* ============================================================
   RQ3
   SQL verifies imbalance and data availability only.
   SMOTE, F2 threshold optimization, and SHAP belong in Python.
   IMPORTANT: apply SMOTE only to TRAIN folds, never before split.
   ============================================================ */
SELECT
    COUNT_BIG(*) AS modeling_rows,
    SUM(CASE WHEN target = 0 THEN 1 ELSE 0 END) AS successful_n,
    SUM(CASE WHEN target = 1 THEN 1 ELSE 0 END) AS unsuccessful_n,
    CAST(100.0 * AVG(CAST(target AS FLOAT)) AS DECIMAL(10,2)) AS unsuccessful_pct
FROM dbo.v_ml_prefinal_dataset;
GO

/* Pipeline quality flags retained for audit */
SELECT
    SUM(CAST(flag_120102baa AS INT)) AS flag_120102baa_n,
    SUM(CAST(flag_suspicious_total AS INT)) AS flag_suspicious_total_n,
    SUM(CAST(flag_no_score_era AS INT)) AS flag_no_score_era_n,
    SUM(CAST(no_assessment_data AS INT)) AS no_assessment_data_n
FROM dbo.ews_cleaned;
GO
